import Foundation
@main struct Bench { static func main() { for fraction in [0.1, 1.0] { for speed in [1.0, 3.0] { var rain = MatrixSimulation(columnCount: 240, rows: 135, glyphCount: 57, density: 1); rain.setSearchFraction(fraction); let start=Date(); for frame in 0...300 { rain.advance(to: Double(frame)/60 * speed) }; var hash: UInt64 = 1469598103934665603; for column in rain.columns { for cell in column.cells { for word in [UInt64(bitPattern: Int64(cell.glyph)), cell.writtenAt.bitPattern, cell.changedAt.bitPattern] { hash = (hash ^ word) &* 1099511628211 } } }; print(fraction, speed, Date().timeIntervalSince(start), rain.visibleSymbolCount, rain.searchingSymbolCount, String(hash,radix:16)) } } } }
